let routeControlsSignature='',lastBattleSite=null,selectedPlannedArea=1,selectedPlannedNode=null,regionMount=null,regionUi=null,lastRegionRefresh=0;
const plannedNodes=()=>typeof MultiEngine.plannedNodes==='function'?MultiEngine.plannedNodes(s,Date.now()):[];
function currentPlannedNode(){const rows=plannedNodes();return rows.find(n=>!e?.done&&n.id===e?.instanceId)||rows.find(n=>n.id===selectedPlannedNode)||rows.find(n=>n.id===s.expedition?.targetInstanceId)||rows.find(n=>n.id===s.expedition?.fieldId)||null;}
function battleHeading(){const node=currentPlannedNode();heading(node?.name||LOCS[s.location]?.name||'选择冒险地点',node?'DWARF · AREA '+node.areaNumber:LOCS[s.location]?.en||'EXPEDITION','<button data-region="dwarf">← 区域地图</button>');$('worldStatus').textContent=node?'推荐 '+node.levelRange.join('–')+'级 · '+(node.kind==='boss'?'首领手动挑战':node.kind==='dungeon'?'普通副本连续3场':'野外持续挂机'):'请在区域地图选择新的冒险地点。';}
function choosePlannedNode(id,startNow=false){const node=plannedNodes().find(n=>n.id===id);if(!node)return toast('地点尚未开放');const tx=persistGameChange(next=>MultiEngine.chooseAdventureNode(next,id,{start:startNow,loop:node.kind==='dungeon'&&!!next.expedition?.loop},Date.now()));if(!tx.ok||!tx.value){if(tx.reason!=='storage')toast('地点未就绪，或需结束当前战斗并停止远征；原计划未改变');return false;}selectedPlannedArea=node.areaNumber;selectedPlannedNode=node.id;finishForgePresentation();e=s.activeEncounter??null;view='battle';if(startNow&&e){lastStep=Date.now();logs.unshift((node.kind==='boss'?'首领现身：':'遭遇 ')+e.name);}render();return true;}
function bindRegionView(){if(view!=='region'||race!=='dwarf')return;const host=$('adjacentRegionHost');if(!host?.addEventListener)return;const initial='dwarf.a'+String(selectedPlannedArea).padStart(2,'0');regionMount=mountRegion(host,{read:()=>buildRegionSnapshot(s,Date.now(),sourceFocus),draw:drawAdjacentRegion,selectArea:id=>{const node=plannedNodes().find(n=>n.areaId===id);if(node)selectedPlannedArea=node.areaNumber;},commitTravel:id=>({ok:choosePlannedNode(id,true)===true,reason:'当前不能前往，原远征计划未改变'}),setFavorite:(id,desired)=>{const tx=persistGameChange(next=>MultiEngine.setFavoriteNode(next,id,desired));return {ok:tx.ok&&!!tx.value,reason:tx.reason==='storage'?'保存失败，收藏未改变':'地点不可收藏'};}},initial,regionUi?.viewAreaId===initial?regionUi:{viewAreaId:initial,previewNodeId:sourceFocus??null});lastRegionRefresh=Date.now();}
function skillTreeView(){heading('技能树草稿','SKILL TREE WORKSHOP');$('worldStatus').textContent='三套独立点数方案 · 草稿确认后统一保存';return '<button data-view="skills">返回战技</button><div id="skillTreeHost"></div>';}
function bindSkillTreeView(){if(view!=='skilltree'&&!(view==='skills'&&s.skillTree?.mode==='active'))return;skillTreeMount=mountSkillTree($('skillTreeHost'),{canActivate:false,getState:()=>s,commit:async payload=>{const config=MultiEngine.SKILL_TREE_DEFINITION;const draft=draftSkillTreePresetPayload(s,config,{baseState:payload.baseState,presets:payload.presets,selectedPreset:payload.baseState.skillTree?.selectedPreset??0,activate:false,confirm:false});if(!draft)return {ok:false,reason:'配置已变化或正在战斗，请取消草稿后重新编辑。'};const quote=quoteSkillTreeDraft(s,draft,config,{confirm:true});if(!quote)return {ok:false,reason:'前置、点数或配置已变化，未提交。'};const tx=persistGameChange(next=>{const prepared=prepareSkillTreeDraft(next,quote,config);if(!prepared)return null;next.skillTree=prepared.game.skillTree;MultiEngine.reconcileSkillTreeHealth(next);if(!MultiEngine.validSave(next))return null;return true;});if(tx.ok&&tx.value){hud();return {ok:true};}return {ok:false,reason:tx.reason==='storage'?'保存失败，草稿保留，当前配置未改变。':'配置变化，未保存，请重新检查。'};}});}
function refreshRegionView(){if(regionMount&&view==='region'&&Date.now()-lastRegionRefresh>=1000){lastRegionRefresh=Date.now();regionMount.refresh();}}

function updateRouteControls(){const host=$('expeditionControlsHost');if(!host)return;const signature=JSON.stringify([s.expedition,s.dungeonRun,!!(e&&!e.done),!!restSeconds(),plannedNodes().map(n=>[n.id,n.unlocked,n.budgetReady,Math.max(0,Math.ceil((n.readyAt-Date.now())/1000))])]);if(signature!==routeControlsSignature){host.innerHTML=routeControls();routeControlsSignature=signature;}}
