function chooseNormalDungeon(startNow=false){const area=currentPlannedNode()?.areaNumber||selectedPlannedArea,node=plannedNodes().find(n=>n.areaNumber===area&&n.kind==='dungeon');if(node)choosePlannedNode(node.id,startNow);else toast('该区域暂无普通副本入口');}
function developmentControls(){return `<details class="developmentControls"><summary>开发测试 · 多敌遭遇</summary><p>克隆当前角色，不影响正式存档。测试数值不是正式怪物平衡；群攻为测试覆盖，不改变已装备战技。</p><button data-developer-group="2">两名敌人</button><button data-developer-group="3">三名敌人</button><button data-developer-group="2" data-test-casting="1">读条 / 控制测试</button>${sandboxSession?'<button data-developer-action="area">测试全体攻击 · 下次行动</button><button data-developer-action="stun">测试当前目标眩晕 · 下次行动</button>':''}</details>`;}
function battleView(){battleHeading();return `<div class="viewport" id="liveBattleViewport"><canvas class="sceneCanvas" id="scene" width="960" height="420" aria-label="像素战斗场景"></canvas><div class="battlePotionHost" id="battlePotionHost">${renderBattlePotionButton(s)}</div><div class="battleBadge"><span class="liveDot"></span><span id="battleState"></span></div><div class="combatStatusBar" id="combatStatuses"></div><div class="hpCards"><div class="hpCard"><div><b>布洛克</b><small id="heroHp"></small></div><div class="healthBar"><i id="heroHpBar"></i></div><div id="playerShieldHost">${renderPlayerShieldSummary(e)}</div></div><div class="hpCard enemy"><div><b id="enemyName"></b><button class="enemyElementInfo" data-elementinfo="1" id="enemyElements" aria-label="查看敌人元素标签和抗性">元素</button><small id="enemyHp"></small></div><div class="healthBar"><i id="enemyHpBar"></i></div></div></div><div class="battleControls"><div class="battleMessage" id="combatMessage">${esc(logs[0]||'炉火照亮了前路。准备出发。')}</div><div class="row"><button class="battleLogBtn" data-log="1">战报</button><button id="bossBtn" class="secondary">挑战首领</button><button data-stopafter="1" id="stopAfterBtn">本场结束后停止</button><button data-camprest="1" id="campRestBtn">营地休息 · 5分钟</button><button id="runBtn" class="primary">开始远征</button></div></div></div><div id="liveBattleCoverage" class="liveBattleCoverage"></div><div id="liveBattleHud"></div><div id="liveBattleDetails" class="liveBattleDetails"></div><div id="enemyRosterHost">${renderEnemyRoster(e)}</div>${developmentControls()}<div id="expeditionControlsHost">${routeControls()}</div><div id="potionPanelHost">${potionView()}</div>`;}
const fmt=n=>Number(n.toFixed(2));
const divineBadge=it=>it.divine?'<small class="divineBadge">神赐</small>':'';
function affixHtml(it){const relic=it.legendaryId?LEGENDARY_CODEX.find(x=>x.id===it.legendaryId&&x.implemented):null;return `<div class="affixBlock">${it.affixes.length?it.affixes.map(a=>{const r=affixRollInfo(a);return `<div class="affixLine roll${r.tier}" title="原始区间 ${r.min}—${r.max}；${RARITY[r.tier]}档"><span>${esc(AFFIX_DEFS[a.stat]?.name||a.stat)}</span><b>+${a.value}${it.divine?`<small class="divineIncrease">（+10%）<br>实际 +${fmt(a.value*1.1)}</small>`:''}</b></div>`}).join(''):''}</div>${relic?`<div class="legendaryExclusive" style="color:#e7bc58"><strong>传说专属 · ${esc(relic.affix)}</strong><p>${esc(relic.effect)}</p></div>`:''}${it.special?`<div class="specialAffix"><strong>特殊词条 · ${esc(SPECIALS[it.special.id].name)}</strong><p>${esc(SPECIALS[it.special.id].desc)}</p></div>`:''}`;}
function equipmentIcon(it){return renderEquipmentIcon(it);}
function itemDetail(it){if(!it)return'<div class="emptyMessage">点击装备查看属性</div>';let on=Object.values(s.equip).includes(it.id),tot=itemTotals(it,{development:s.developmentEquipmentSandbox===true}),template=MultiEngine.equipmentTemplateDisplay(it);return `<span class="detailIcon ${it.set?'setFrame':''}">${equipmentIcon(it)}</span><h3 class="r${it.rarity}text">${esc(it.name)}${enhancementLevel(it)?' +'+enhancementLevel(it):''}${divineBadge(it)}</h3><span class="rarityText" title="${esc(equipmentLevelTitle(it))}">${RARITY[it.rarity]} / ${SLOTNAME[it.slot]} / LV.${it.level}${template?.typeName?' · '+esc(template.typeName):''}</span>${equipmentBudgetNotice(it)?`<p class="subtleText">${esc(equipmentBudgetNotice(it))}</p>`:''}${template&&!template.legacy?`<p class="subtleText">${esc(template.description)} · 矮人工艺</p>`:''}<div class="affixLabel">基础属性 · 原始数值</div><div class="itemStats">${[['atk','攻击'],['armor','护甲'],['hp','生命']].map(([k,n])=>`<div><b>${it[k]}${it.divine&&it[k]?'<small class="divineIncrease">（+10%）</small>':''}</b><small>${n}</small>${it.divine||enhancementLevel(it)?`<small>实际 ${fmt(tot[k])}</small>`:''}</div>`).join('')}</div>${affixHtml(it)}${it.set?`<div class="setDetail"><strong>${BUILD.find(b=>b.id===it.set).name}套装</strong><p>${BUILD.find(b=>b.id===it.set).bonus}</p></div>`:''}${it.divine?'<p class="subtleText">神赐提升基础与普通数值词条10%；保留小数后汇总，不重复加成，不放大特殊概率或套装效果。</p>':''}<div class="detailActions"><button data-enhance-item="${esc(it.id)}">强化</button>${it.slot==='ring'?['ring1','ring2'].map(k=>`<button class="primary" data-equip="${it.id}" data-socket="${k}" ${s.equip[k]===it.id?'disabled':''}>${s.equip[k]===it.id?'已戴':'装备'}${k==='ring1'?'戒指Ⅰ':'戒指Ⅱ'}</button>`).join(''):`<button class="primary" data-equip="${it.id}" ${on?'disabled':''}>${on?'已装备':'装备'}</button>`}<button data-lock="${it.id}">${it.locked?'解锁':'锁定'}</button><button data-sell="${it.id}" ${on||it.locked||isProtected(s,it.id)?'disabled':''}>出售 ${sellValue(it)}◈</button></div>`;}
function sortedGear(bagOnly=false){return [...(bagOnly?bagItems(s):s.inventory)].sort((a,b)=>bagSort==='slot'?SLOTS.indexOf(a.slot)-SLOTS.indexOf(b.slot)||b.rarity-a.rarity:bagSort==='level'?b.level-a.level||b.rarity-a.rarity:b.rarity-a.rarity||b.level-a.level);}
function forgeTabs(){return (s.pendingForgeClaim?'<div class="pendingForgeBanner forgeClaimBanner" role="status"><span>成品已保存 · 领取前不能再次融合</span><button data-forgeclaim="1">领取成品</button><button data-view="inventory">整理背包</button></div>':'')+(s.pendingReforge?`<div class="pendingForgeBanner" role="status"><span>有一份已付费的改造结果等待选择</span><button data-reforgeresume="1">查看对照</button></div>`:'')+`<div class="forgeTabs"><button data-forgetab="fusion" class="${forgeTab==='fusion'?'active':''}">自由融合</button><button data-forgetab="modify" class="${forgeTab==='modify'?'active':''}">装备改造</button><button data-forgetab="enhancement" class="${forgeTab==='enhancement'?'active':''}">装备强化</button><button data-forgetab="recipes" class="${forgeTab==='recipes'?'active':''}">固定配方</button></div>`;}
function reforgeCostLabel(cost){return `${cost.gold?cost.gold+' ◈':cost.equipment?'祭品装备 ×1':''}${Object.entries(cost.materials||{}).map(([k,v])=>`<span>${icon(matIcon[k])}${k} ×${v}<small>普通余额 ${materialCount(s,k,0)}</small></span>`).join('')}${Object.entries(cost.consumables||{}).map(([k,v])=>`<span>${icon('reforgeToken')}重铸印记 ×${v}<small>持有 ${s.consumables?.[k]||0}</small></span>`).join('')}`;}
function pendingReforgeView(){
 const p=s.pendingReforge,it=s.inventory.find(x=>x.id===p.itemId);if(!it)return '<div class="emptyMessage">目标装备缺失，请导出存档备份。</div>';
 const oldItem={...it,affixes:p.oldAffixes,special:p.ruleVersion>=2?p.oldSpecial:it.special,divine:p.ruleVersion>=5?p.oldDivine:it.divine},newItem=getPendingReforgeCandidate(s);if(!newItem)return '<div class="emptyMessage">改造候选无效，请导出存档备份。</div>';
 const side=(candidate,which,label)=>{const totals=itemTotals(candidate,{development:s.developmentEquipmentSandbox===true});return `<section data-reforge-side="${which}"><h3>${label}</h3><h4>${esc(candidate.name)}${divineBadge(candidate)}</h4><p class="subtleText" data-reforge-base="${which}">基础生效：攻击 ${fmt(totals.atk)} · 生命 ${fmt(totals.hp)} · 护甲 ${fmt(totals.armor)}${candidate.divine?'（神赐 +10% 已计入）':''}</p>${affixHtml(candidate)}</section>`;};
 return `<div class="panelPage pendingReforge" data-operation="${esc(p.operationId)}"><div class="modifyTitle"><span class="detailIcon ${it.set?'setFrame':''}">${equipmentIcon(it)}</span><h3 class="r${it.rarity}text">${esc(it.name)}${divineBadge(it)}</h3></div><div class="reforgeComparison">${side(oldItem,'old','原属性 <small>当前生效</small>')}${side(newItem,'new','新属性 <small>待选择</small>')}</div><p class="subtleText">费用已支付：${reforgeCostLabel(p.cost)}${p.donor?' · '+esc(p.donor.name):''}。保留原属性不会退还费用。装备原始基础数值、品质、等级、部位、套装与强化不改变。全部重铸可能获得神赐，已有神赐保留；新神赐与特殊词条只在采用新属性后生效。</p><div class="reforgeChoices"><button data-reforgechoice="keep" data-operation="${esc(p.operationId)}">保留原属性</button><button class="primary" data-reforgechoice="accept" data-operation="${esc(p.operationId)}">采用新属性</button></div><p class="subtleText">离开界面不会替你选择。刷新后仍是这一份结果；确认前不能再次改造或出售该装备。</p></div>`;
}
function persistGameChange(action,commitOnNoop=false){if(runtimeStorageBlocked)return {ok:false,game:s,value:null,reason:"storage-blocked"};const result=commitGameTransaction(activeGameStorage(),s,action,{commitOnNoop});if(!result.ok){if(result.reason==='storage'){$('saveStatus').textContent='保存失败 · 操作未提交';toast('保存失败，操作未提交：资源与物品未改变。请导出备份并释放存储空间后重试。');}return result;}s=result.game;e=normalizeEncounterElements(s.activeEncounter??null);$('saveStatus').textContent='已自动保存';return result;}
let preparedReforgeAttempt=null,preparedReforgeError='';
function reforgeSourceFingerprint(game){const copy=structuredClone(game);delete copy.lastSeen;delete copy.offlineLuck;delete copy.lastHealthClock;return JSON.stringify(copy);}
function generatePreparedReforge(){
 preparedReforgeError='';
 const key=JSON.stringify([modifyId,modifyMode,modifyIndex,modifyDonorId]),source=reforgeSourceFingerprint(s),storage=activeGameStorage();
 if(preparedReforgeAttempt&&(preparedReforgeAttempt.key!==key||preparedReforgeAttempt.source!==source||preparedReforgeAttempt.storage!==storage)){
  preparedReforgeAttempt=null;preparedReforgeError='装备、资源或战斗状态已变化；未付款结果已作废。请核对当前选择后再次生成。';return null;
 }
 if(!preparedReforgeAttempt){const next=structuredClone(s),value=reforge(next,modifyId,modifyMode,modifyIndex,modifyDonorId);if(!value)return null;preparedReforgeAttempt={key,source,storage,next,value};}
 const prepared=preparedReforgeAttempt;
 const result=persistGameChange(next=>{if(reforgeSourceFingerprint(next)!==prepared.source)return null;const healthClock=next.lastHealthClock;for(const k of Object.keys(next))delete next[k];Object.assign(next,structuredClone(prepared.next));if(healthClock!==undefined)next.lastHealthClock=healthClock;return structuredClone(prepared.value);});
 if(result.ok){preparedReforgeAttempt=null;return result.value;}
 if(result.reason!=='storage')preparedReforgeAttempt=null;else preparedReforgeError='保存失败，尚未扣费；再次点击将重试同一结果。刷新页面会丢失此未付款结果。';
 return null;
}
function persistReforgeChange(action){const result=persistGameChange(action);return result.ok?result.value:null;}

function donorPicker(it){const rows=eligibleReforgeDonors(s,it.id,modifyIndex);return `<div class="donorPicker"><h4>选择祭品装备</h4><div class="donorGrid">${rows.map(({item,affixes})=>`<button data-modifydonor="${item.id}" class="donorCard r${item.rarity} ${item.set?'setFrame':''} ${modifyDonorId===item.id?'selected':''}">${equipmentIcon(item)}<b>${esc(item.name)}</b><small>${affixes.map(a=>`<span class="roll${affixRollInfo(a).tier}">${esc(AFFIX_DEFS[a.stat].name)} +${a.value}</span>`).join(' / ')}</small></button>`).join('')||'<p class="subtleText">没有可用祭品：需未穿戴、未锁定、未被方案引用，且含不与其他保留词条重复的普通词条。</p>'}</div><p class="subtleText">随机抽取祭品的一条可用普通词条，属性与原始数值原样继承；可替换为同类型，不与其他保留词条重复。祭品神赐不转移；目标已有神赐仍生效一次。生成候选即消耗祭品，保留原属性也不会返还。</p></div>`;}
function modifyView(){if(s.pendingReforge)return pendingReforgeView();const it=s.inventory.find(x=>x.id===modifyId),cost=it?getReforgeCost(it,modifyMode):null,can=cost&&s.gold>=cost.gold&&Object.entries(cost.materials||{}).every(([k,v])=>materialCount(s,k,0)>=v)&&Object.entries(cost.consumables||{}).every(([k,v])=>(s.consumables?.[k]||0)>=v)&&(modifyMode!=='replace'||eligibleReforgeDonors(s,it.id,modifyIndex).some(x=>x.item.id===modifyDonorId));return `<div class="panelPage modifyLayout"><div><div class="sectionLabel">选择装备</div><div class="bagGrid">${sortedGear().map(x=>`<button class="itemCell r${x.rarity} ${x.set?'setFrame':''} ${modifyId===x.id?'selected':''}" data-modifyitem="${x.id}" title="${esc(x.name)}">${equipmentIcon(x)}${x.locked?'<span class="lockedDot">◆</span>':''}</button>`).join('')}</div></div><div>${it?`<div class="modifyTitle"><span class="detailIcon ${it.set?'setFrame':''}">${equipmentIcon(it)}</span><h3 class="r${it.rarity}text">${esc(it.name)}${divineBadge(it)}</h3><small>${RARITY[it.rarity]} · ${SLOTNAME[it.slot]}${it.locked?' · 已锁定（防出售，不阻止明确改造）':''}</small></div><div class="modifyModes">${[['value','数值洗练'],['replace','替换一条'],['all','全部重铸']].map(([k,n])=>`<button data-modifymode="${k}" class="${modifyMode===k?'active':''}">${n}</button>`).join('')}</div><div class="modifyAffixes">${it.affixes.map((a,i)=>{let r=affixRollInfo(a);return `<button data-modifyindex="${i}" class="roll${r.tier} ${modifyIndex===i&&modifyMode!=='all'?'active':''}" ${modifyMode==='all'?'disabled':''}><span>${AFFIX_DEFS[a.stat].name}</span><b>+${a.value}${it.divine?'<small class="divineIncrease">（+10%）</small>':''}</b></button>`}).join('')||'<p>该装备没有普通词条，不能进行此类改造。</p>'}</div>${modifyMode==='replace'?donorPicker(it):''}<p class="modifyHint">${{value:'仅重掷选中词条的数值，可能提高、降低或不变。',replace:'消耗1件祭品装备，随机继承其一条可用普通词条的属性与原始数值，不与其他保留词条重复，可替换为同类型。',all:'消耗1枚重铸印记，重掷全部普通词条；优良和至臻非套装、非传说装备必有1条特殊词条，可能与原词条相同；可偶遇神赐，已有神赐保留。'}[modifyMode]}</p>${cost?`<div class="modifyCost">${reforgeCostLabel(cost)}</div>`:''}${modifyResult?`<div class="modifyResult" role="status"><strong>改造完成 · 已保存</strong>${modifyResult.before.map((a,i)=>`<p>${AFFIX_DEFS[a.stat].name} +${a.value} → ${AFFIX_DEFS[modifyResult.after[i].stat].name} +${modifyResult.after[i].value}</p>`).join('')}<button data-modifycontinue="1">继续改造</button></div>`:`<button class="primary" data-modifycommit="1" ${!can||!modifyReady?'disabled':''}>付费生成预览${!can&&cost?(modifyMode==='replace'?' · 请选择可用祭品':' · 资源不足'):''}</button>`}<p class="subtleText">数值洗练使用金币与普通材料；替换消耗祭品；全部重铸消耗印记。高品质材料不会自动抵扣。保留装备品质、等级、部位、原始基础数值、套装与强化，已有神赐保留。付费后可对照新旧属性；保留原属性不退费用。候选结果保存后不会重掷，不会新增词条。数值洗练与单条替换不改变特殊词条；全部重铸可改变优良及至臻非套装散件的特殊词条；传说固定专属始终保留。重铸印记来自首领和游商。</p>`:'<div class="emptyMessage">从左侧选择一件装备</div>'}</div></div>`;}
function inventoryView(){heading('旅人行囊','EQUIPMENT & RELICS',`<button data-view="loadouts">装备柜</button> <button data-stats="1">角色属性</button> ${bagTab==='equipment'?'<button data-sellall="1">批量出售</button>':''}`);$('worldStatus').textContent='各部位独立50格；戒指共用一包。道具药剂与材料各100个堆叠。';return (s.pendingForgeClaim?'<div class="pendingForgeBanner"><span>熔炉成品已保存，等待领取</span><button data-view="forge">前往锻炉</button></div>':'')+renderInventory(s,{bagTab,bagSlot,bagSort,selected,sortedGear:()=>sortedGear(true),itemDetail,potionView,materialGrid});}
function loadoutsView(){heading('构筑装备柜','GEAR & RUNES','<button data-view="inventory">← 背包</button>');$('worldStatus').textContent='一套装备与战技，一次切换。天赋独立。';return `${s.running||e&&!e.done?`<div class="loadoutBattleNotice">先结束当前远征再切换方案。<button data-stopafter="1">${s.stopAfterBattle?'取消结束后停止':'本场结束后停止'}</button><button data-loadoutretreat="1">撤回营地</button></div>`:''}`+renderLoadouts(s,{wardrobeIds,bagItems});}
function elementTable(attack,resistance){return `<div class="elementTable">${ELEMENT_KEYS.map(k=>`<div data-element-stat="${k}"><span class="elementGlyph element-${k}">${ELEMENTS[k].name}</span>${attack?`<span>技能增幅 <b>${fmt(attack[k]||0)}</b></span>`:''}<span>抗性 <b>${fmt(resistance?.[k]||0)}</b></span></div>`).join('')}</div>`;}
function showStats(){let st=stats(s);modal(`<div class="eyebrow">DWARVEN ATTRIBUTES</div><h2>布洛克的属性</h2><div class="characterStats">${[['生命',st.hp],['攻击',st.atk],['护甲',st.armor],['命中值 / 实际命中率',st.hitRating+' / '+(st.hit*100).toFixed(1)+'%'],['暴击值 / 实际暴击率',st.critRating+' / '+(st.crit*100).toFixed(1)+'%'],['暴伤值 / 伤害倍率',st.critDamageRating+' / '+st.critDamage.toFixed(2)+'×'],['元素技能增幅',fmt(st.element)],['火技能增幅',fmt(st.elementAttack?.fire||0)],['火抗性',fmt(st.elementResistance?.fire||0)],['物理穿甲',st.penetration||0],['格挡率',(100*(st.block||0)).toFixed(1)+'%'],['护盾额外值',st.shieldBonus||0],['主动治疗额外值',st.healingBonus||0],['有效幸运值',fmt(st.luck||0)],['吸血值 / 实际吸血率',fmt(st.lifestealRating||0)+' / '+(100*(st.lifestealRate||0)).toFixed(1)+'%']].map(([n,v])=>`<div><span>${n}</span><b>${v}</b></div>`).join('')}</div><details class="elementDetails"><summary>六元素明细</summary>${elementTable(st.elementAttack,st.elementResistance)}<p class="subtleText">六系装备增幅与抗性均可随机出现；当前可用元素战技为火系，其余五系战技尚未开放。通用天赋数值已计入上表。</p></details><p class="subtleText">元素增幅仅强化对应元素技能，不为普攻或物理战技附魔。元素伤害由增幅与对应抗性的差值结算；克制目标任一标签时额外提高10%，不重复叠加。</p>`);}
function showEnemyElements(){if(!e)return;modal(`<div class="eyebrow">ENEMY ELEMENTS</div><h2>${esc(e.name)}</h2><div class="enemyTagList">${(e.elementTags||[]).map(k=>`<span class="elementGlyph element-${k}" data-enemy-element="${k}">${ELEMENTS[k]?.name||''}</span>`).join('')||'<span class="subtleText">无元素标签</span>'}</div>${elementTable(null,e.elementResistance)}<p class="subtleText">标签用于克制判定，不限制攻击类型。光暗互克；地克水、水克火、火克风、风克地。多个标签最多触发一次10%加成，物理伤害不受此加成。</p>`);}

function skillsView(){return renderBuildPicker(s)+skillTreeView();}
function premiumLootText(loot=[]){return loot.filter(m=>m.quality>0).map(m=>RARITY[m.quality]+m.material+'×'+m.count).join('、');}
function materialVisual(key){const m=parseMaterialKey(key);return m?icon(matIcon[m.material],'anvil',m.quality):'';}
function materialLabel(key){const m=parseMaterialKey(key);return m?RARITY[m.quality]+' '+(MATERIALS[m.material]?.name??m.material):'空材料槽';}
function materialGrid(forForge=false){return `<div class="materialStackGrid">${materialEntries(s).filter(m=>!forForge||forgeTab!=='recipes'||currentRecipe()?.ingredients?.some(i=>i.material===m.material)).map(m=>`<button class="materialStack r${m.quality}" ${forForge?`data-material="${m.key}"`: `data-materialinfo="${m.key}"`} title="${RARITY[m.quality]} ${esc(MATERIALS[m.material]?.name??m.material)} · ${esc(MATERIALS[m.material].description)}" ${forgeBusy&&forForge?'disabled':''}>${materialVisual(m.key)}<b class="r${m.quality}text">${esc(MATERIALS[m.material]?.name??m.material)}</b><span>×${m.count}</span>${forForge&&selection.filter(k=>k===m.key).length?`<small>已放 ${selection.filter(k=>k===m.key).length}</small>`:''}</button>`).join('')||'<span class="subtleText">暂无材料</span>'}</div>`;}
function currentRecipe(){const all=Object.values(RECIPES).filter(r=>r.enabled);if(!all.some(r=>r.id===selectedRecipe))selectedRecipe=all.find(r=>recipeKnown(s,r.id))?.id??all[0]?.id??null;return RECIPES[selectedRecipe]??null;}
function recipeRequirements(r){return r.ingredients.map(i=>{const used=selection.filter(k=>parseMaterialKey(k)?.material===i.material).length;return `<span class="recipeNeed ${used===i.count?'is-ready':''}">${icon(matIcon[i.material])}<b>${i.material}</b><small>${used} / ${i.count}</small></span>`;}).join('');}
function recoveryQuote(){return quoteRecoveryRecipe(s,recoveryQuality,Object.entries(recoveryQuantities).filter(([,quantity])=>quantity>0).map(([key,quantity])=>({key,quantity})));}
function potionRecipeQuote(){return MultiEngine.quotePotionRecipe(s,potionRecipeId,potionRecipeQuality,{mainKey:potionRecipeMain,auxKey:potionRecipeAux,quantity:potionRecipeBatch});}
function recipeForgeView(){return forgeTabs()+renderPotionRecipePicker(s,potionRecipeId)+(potionRecipeId==='potion-healing'?renderRecoveryRecipe(s,{quality:recoveryQuality,quantities:recoveryQuantities,quote:recoveryQuote(),error:recoveryError,busy:forgeBusy||!!s.pendingForgeClaim}):renderPotionRecipe(s,{id:potionRecipeId,quality:potionRecipeQuality,mainKey:potionRecipeMain,auxKey:potionRecipeAux,quantity:potionRecipeBatch,quote:potionRecipeQuote(),error:potionRecipeError,busy:forgeBusy||!!s.pendingForgeClaim}));}
function commitPotionRecipe(){if(forgeBusy||s.pendingForgeClaim)return;const quote=potionRecipeQuote();if(!quote){potionRecipeError='请选择同品质主辅材料，并检查数量与金币';render();return;}const tx=persistGameChange(next=>MultiEngine.craftPotionRecipe(next,quote));if(!tx.ok){potionRecipeError=tx.reason==='storage'?'保存失败，材料与金币未改变，可重试。':'材料或金币已变化，请重新检查。';render();return;}lastForgeResult=tx.value;potionRecipeMain='';potionRecipeAux='';potionRecipeBatch=1;potionRecipeError='';render();showForgeResult();}
function setRecoveryQuantity(key,value){const row=eligibleRecoveryMaterials(s,recoveryQuality).find(m=>m.key===key);if(!row||s.pendingForgeClaim)return;const others=Object.entries(recoveryQuantities).reduce((n,[k,q])=>n+(k===key?0:q),0);if(!Number.isSafeInteger(value)||value<0){recoveryError='请输入有效的非负整数数量';render();return;}recoveryQuantities[key]=Math.min(value,row.count,Math.max(0,RECOVERY_RECIPE_CONFIG.maxBatch-others));recoveryError='';render();}
function commitRecovery(){if(s.pendingForgeClaim||forgeBusy)return;const quote=recoveryQuote();if(!quote){recoveryError='请选择已掌握配方的同品质材料，并检查金币与数量';render();return;}const tx=persistGameChange(draft=>craftRecoveryRecipe(draft,quote));if(!tx.ok){recoveryError=tx.reason==='storage'?'保存失败，材料与金币未改变，可重试。':'材料、金币或待领取成品已变化，请重新检查。';render();return;}lastForgeResult=tx.value;recoveryQuantities={};recoveryError='';render();showForgeResult();}
function showPotionSettings(){modal(renderPotionSettings(s));potionSettingsOpen=true;}
function potionAction(action){syncLiveBattle();let batch;const tx=persistGameChange(next=>{batch=liveEvents.capture(next.activeEncounter??null,()=>action(next));return batch.result;});if(tx.ok){render();publishLiveBatch(batch);if(potionSettingsOpen&&$('modal').open)showPotionSettings();}return tx.ok;}

function currentForgeResult(){const p=s.pendingForgeClaim;if(p)return p.kind==='equipment'?p.item:p.potion;return typeof lastForgeResult==='object'?lastForgeResult:s.inventory.find(i=>i.id===lastForgeResult);}
function claimPendingForge(){if(!s.pendingForgeClaim)return;const tx=persistGameChange(next=>claimForgeResult(next));if(!tx.ok){if(tx.reason!=='storage')toast('对应背包仍无空位，成品继续保存在熔炉，不会再次扣费');return;}const out=tx.value;lastForgeResult=out.kind==='potion'?out:out.id;if(out.kind!=='potion'){selected=out.id;bagSlot=out.slot;}if($('modal').open)$('modal').close();render();toast('成品已领取并保存，没有再次消耗金币或材料');}
function showForgeResult(){const result=currentForgeResult();if(!result)return;const pending=!!s.pendingForgeClaim;if(result.kind==='potion'){modal(`<span class="detailIcon r${result.quality}">${icon(POTIONS[result.potionType].icon)}</span><h2 class="r${result.quality}text">${esc(result.name)} ×${result.quantity??1}</h2><p>${RARITY[result.quality]} · ${pending?'已完成 · 等待领取':'已收入药剂库存'}</p><p>${potionDescription(result.potionType,result.quality)}</p>${pending?'<button class="primary" data-forgeclaim="1">领取成品</button>':`<button data-potionselect="${result.key}">携带此药剂</button>`}`);return;}modal(`<div class="eyebrow">FORGED IN EMBERS</div><h2>${pending?'锻造完成 · 等待领取':result.divine?'神赐降临 · 炉火眷顾':'锻造成品'}</h2>${result.divine?'<div class="divineBanner">炉火回应了你的祈愿。成品基础属性与普通数值词条获得永久提升。</div>':''}<div class="itemDetail">${pending?itemDetail(result).replace(/<div class="detailActions">[\s\S]*$/,'')+'<button class="primary" data-forgeclaim="1">领取成品</button>':itemDetail(result)}</div>`);}
function fusionInputSnapshot(ref){if(typeof ref==='string'){const m=parseMaterialKey(ref);return {kind:'material',key:ref,quality:m?.quality??0,label:m?materialLabel(ref):'材料已失效',html:m?materialVisual(ref):icon('bag'),set:false};}const it=s.inventory.find(x=>x.id===ref?.id);return {kind:'equipment',id:ref?.id,quality:it?.rarity??0,label:it?it.name+' · LV.'+it.level:'装备已失效',html:it?equipmentIcon(it):icon('bag'),set:!!it?.set};}
function fusionPicker(){return renderForgeInputPicker(s,{tab:fusionInputTab,slot:fusionFamily,page:fusionPage,selection:forgeBusy?forgeInputs:selection,busy:forgeBusy||!!s.pendingForgeClaim,materialGrid:()=>materialGrid(true),eligibleEquipment:eligibleFusionEquipment(s)});}
function forgeStage(){const result=currentForgeResult(),pending=!!s.pendingForgeClaim,inputs=forgeBusy?forgeInputs:selection.map(fusionInputSnapshot),points=[[-110,-48],[0,-90],[110,-48],[-76,78],[76,78]];return `<div class="fusionStage ${forgeBusy?'is-forging':''} ${result?.divine&&!forgeBusy?'is-divine':''}"><div class="forgeCircle"></div>${Array.from({length:5},(_,i)=>`<button class="orbitSlot ${inputs[i]?'filled r'+inputs[i].quality+(inputs[i].set?' setFrame':''):''}" style="--sx:${points[i][0]}px;--sy:${points[i][1]}px;--delay:${i*45}ms" data-remove="${i}" title="${inputs[i]?esc(inputs[i].label+' · 点击移除'):'空投入槽'}" ${forgeBusy?'disabled':''}>${inputs[i]?inputs[i].html:'<span>+</span>'}</button>`).join('')}<div class="forgeCore ${result&&!forgeBusy?'has-result':''}">${forgeBusy?`<span class="forgeFlame">${icon('fire')}</span>`:result?`<button class="forgeResult r${result.quality??result.rarity} ${result.set?'setFrame':''}" data-forgeresult="${result.kind==='potion'?'potion':result.id}" title="查看${esc(result.name)}">${result.kind==='potion'?icon(POTIONS[result.potionType].icon,'anvil',result.quality):equipmentIcon(result)}</button>`:`<span class="idleForge">${icon('forge')}</span>`}<span class="pixelBurst"></span></div></div>${forgeBusy?'<div class="forgeOutcome forgingText" role="status">炉火正在凝聚…</div>':result?`<div class="forgeOutcome" role="status">${result.divine?'<strong class="forgeDivineTitle">✧ 神赐降临 · 炉火眷顾</strong>':''}<strong class="r${result.quality??result.rarity}text">${esc(result.name)}${divineBadge(result)}</strong><small>${RARITY[result.quality??result.rarity]} · ${pending?'对应背包已满 · 已付费保存，等待领取':result.kind==='potion'?'药剂 · 点击查看与携带':SLOTNAME[result.slot]+' · 点击成品查看与装备'}</small>${pending?'<button class="primary" data-forgeclaim="1">领取成品</button><button data-view="inventory">整理对应背包</button>':'<button data-forgecontinue="1">继续融合</button>'}</div>`:'<div class="forgeOutcome"><small>放入 1—5 份装备或材料，点燃熔炉</small></div>'}`;}
function forgeView(){heading('黑炉锻坊','THE LAST EMBERS');if(forgeTab==='workshop'&&sandboxSession?.kind==='equipment'){if(!workshopQuote&&!workshopResult)refreshWorkshopQuote();$('worldStatus').textContent='装备开发试验台：候选费用与强化幅度，仅作用于角色副本。';return renderEquipmentWorkshop(s,{selectedId:workshopItem,selectedTemplate:workshopTemplate,quote:workshopQuote,lastResult:workshopResult,busy:workshopBusy,error:workshopError});}if(forgeTab==='enhancement'){enhancementItem??=s.equip.weapon;if(!enhancementQuote&&!enhancementResult)enhancementQuote=quoteEnhancement(s,enhancementItem);$('worldStatus').textContent='消耗金币强化装备基础；失败同样扣费并降低一级。';return forgeTabs()+renderFormalEnhancement(s,{itemId:enhancementItem,quote:enhancementQuote,receipt:enhancementResult,error:enhancementError,busy:enhancementBusy});}if(forgeTab==='recipes'){$('worldStatus').textContent='固定配方永久掌握；同品质材料产出同品质药剂，可批量制作。';return recipeForgeView();}if(forgeTab==='modify'){$('worldStatus').textContent='选择装备与普通词条，确认后才消耗资源并随机。';return forgeTabs()+modifyView();}$('worldStatus').textContent='自由融合：含装备时产出随机散件；纯材料仍可能炼出药剂。';return forgeTabs()+`<div class="viewport"><canvas class="workshopCanvas" id="forgeCanvas" width="960" height="320" aria-label="像素矮人锻造工坊"></canvas><div class="workshopBottom forgeWorkshop">${forgeStage()}${fusionPicker()}<div class="craftControls"><button id="forgeBtn" class="primary" ${forgeBusy||s.pendingForgeClaim?'disabled':''}>${forgeBusy?'熔炼中…':s.pendingForgeClaim?'先领取已完成成品':'点燃熔炉 · 40◈'}</button><button data-workshop-open="1">装备试验台</button><button id="blessBtn" ${forgeBusy?'disabled':''}>装备强化</button></div><details class="fusionRules"><summary>融合规则与品质说明</summary><p class="subtleText">最多5份投入，共需40金币；选中的装备和材料会被消耗。含装备时只生成随机非套装装备，不复制原词条或神赐；纯材料含灰根草时仍可能炼出药剂。<br>装备融合综合全部投入品质，更多同品质装备更有利；品质可能升高、持平或降低。投入低品质材料可能稀释高品质装备。至臻装备与优质材料更易引来神赐，但不保证出现；幸运轻微改善品质与神赐机会。矮人的祖炉眷顾常驻，不占技能槽或技能点，不随方案切换；改善锻造的有利随机机会，不改变费用或原值继承（RAW）的数值。<br>含装备时，等级按最高保留基准上下浮动，不累积前次浮动；纯材料锻造仍为角色当前等级。对应背包满时保留一份已付费成品，领取前不能再次融合。<br>投入传说时保底至臻散件，传说本身会消耗；成品强化从 +0 开始，不继承专属。融合装备全部为非套装；套装仅在第3区域起的普通与首领副本产出，当前已开放矮人第1–6区域。优良及以上散件可能带额外特殊词条，传说不会由普通品质升档获得。<br>神赐使基础属性与普通数值词条 +10%，特殊概率不变；品质、等级与神赐分别处理。隐藏配方仍未实装。</p></details></div></div>`;}
function finishForgePresentation(){const wasBusy=forgeBusy;if(forgeTimer!==null)clearTimeout(forgeTimer);forgeTimer=null;forgeEpoch++;forgeBusy=false;forgeInputs=[];if(wasBusy&&view==='forge')render();}
function beginForge(){if(forgeBusy)return;if(s.pendingForgeClaim)return toast('请先领取已保存的熔炉成品，再开始新的融合');const inputs=selection.map(ref=>typeof ref==='string'?ref:{...ref}),visuals=inputs.map(fusionInputSnapshot),tx=persistGameChange(next=>forgeTab==='recipes'?craftRecipe(next,selectedRecipe,inputs):forge(next,inputs));if(!tx.ok){if(tx.reason!=='storage')toast(forgeTab==='recipes'?'请确认已学习配方、投入种类数量和金币':'需要1—5份有效装备或材料与40金币；锁定、穿戴、方案引用、待改造或重复装备不能投入');return;}const out=tx.value;lastForgeResult=out.kind==='potion'?out:out.id;if(out.kind!=='potion')selected=out.id;selection=[];forgeInputs=visuals;forgeBusy=true;const epoch=++forgeEpoch;render();const reduced=typeof window.matchMedia==='function'&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;const reveal=()=>{if(epoch!==forgeEpoch)return;forgeTimer=null;forgeBusy=false;forgeInputs=[];if(view==='forge')render();};if(reduced)reveal();else forgeTimer=setTimeout(reveal,1100);}

function merchantCountdown(shop){const seconds=Math.max(0,Math.ceil((shop.nextRefreshAt-Date.now())/1000));return '自动换货 '+Math.floor(seconds/60)+':'+String(seconds%60).padStart(2,'0');}
let merchantRetryAt=0,merchantStorageFailed=false;
function refreshMerchantSafely(force=false){const m=s.merchant,now=Date.now(),needs=!m||m.cycleStart===undefined||m.offers.length!==8||now>=m.nextRefreshAt;if(!needs)return m;if(!force&&now<merchantRetryAt)return m||null;const tx=persistGameChange(next=>ensureMerchant(next,now));if(!tx.ok){merchantRetryAt=now+5000;merchantStorageFailed=true;return m||null;}merchantRetryAt=0;merchantStorageFailed=false;return s.merchant;}
function merchantTick(){if(view!=='merchant')return;const rev=s.merchant?.revision,shop=refreshMerchantSafely();if(!shop)return;if(rev!==shop.revision){buyQuantities={};render();}else if($('merchantTimer'))$('merchantTimer').textContent=merchantCountdown(shop);}

function maxPurchase(offer){const key=materialKey(offer.material,offer.quality??0);if(!canReceiveMaterial(s,key,1))return 0;return Math.max(0,Math.min(offer.stock,Math.floor(s.gold/offer.price),1e12-materialCount(s,offer.material,offer.quality??0)));}
function shopEquipmentCard(o,revision){const it=o.item;return `<article class="commodityCard equipmentCommodity"><div class="shopGearIcon ${it.set?'setFrame':''}">${equipmentIcon(it)}</div><h3 class="r${it.rarity}text">${esc(it.name)}</h3><small title="${esc(equipmentLevelTitle(it))}">${RARITY[it.rarity]} · ${SLOTNAME[it.slot]} · LV.${it.level}</small>${!isMerchantEquipmentSellable(o)?'<p class="subtleText">历史套装 · 已停售</p>':''}<div class="shopGearPrice">${o.price} ◈</div><button data-shop-detail="${o.offerId}" data-shop-quote="${revision}" ${!o.stock?'disabled':''}>${!o.stock?'售罄':isMerchantEquipmentSellable(o)?'查看装备':'查看停售装备'}</button></article>`;}
function merchantView(){heading('尼克的行囊','THE GOBLIN TRADER');$('worldStatus').textContent='“盟约碎了，买卖还得做。” —— 哥布林行商尼克';const shop=refreshMerchantSafely();if(!shop)return '<div class="emptyMessage">货单未能保存，尚未生成可购买商品。<button data-shopretry="1">重试读取货单</button></div>';shopQuote=shop.revision;const gearRange=getMerchantEquipmentLevelRange(s);return `<div class="viewport"><canvas class="workshopCanvas" id="merchantCanvas" width="960" height="320" aria-label="像素哥布林商人摊位"></canvas><div class="workshopBottom"><div class="merchantStockHeader"><strong>行商货单${merchantStorageFailed?'<small>新货未能保存 · 暂显示原货单</small>':''}</strong><span>按件购买 · 不限当前副本</span></div><p class="merchantProgressNote">下次换货装备等级：${gearRange[0]}–${gearRange[1]} · 按最高已解锁区域<br><small>当前货单保持原样；未开放区域的解锁记录也计入货品等级。</small></p><div class="commodityGrid">${shop.offers.map((o,i)=>{if(o.type==='equipment')return shopEquipmentCard(o,shop.revision);if(o.type==='recipe'){const r=RECIPES[o.recipeId],known=recipeKnown(s,o.recipeId);return `<article class="commodityCard equipmentCommodity recipeCommodity">${icon('recipeScroll')}<h3>${r.name}</h3><small>固定药剂配方 · 永久学习</small><p>${r.id==='potion-healing'?'同品质恢复材料 ×1': '同品质主材料 ×1 ＋ 辅助材料 ×1'}</p><div class="shopGearPrice">${o.price} ◈</div><button data-buy-recipe="${o.offerId}" data-shop-quote="${shop.revision}" ${known||!o.stock||s.gold<o.price?'disabled':''}>${known?'已掌握':!o.stock?'售罄':'购买并永久学习'}</button></article>`;}if(o.type==='consumable'){const token=o.consumable==='reforgeToken';return `<article class="commodityCard equipmentCommodity ${token?'tokenCommodity':'fruitCommodity'}">${icon(token?'reforgeToken':'memoryfruit')}<h3>${token?'重铸印记':'回忆之果'}</h3><small>${token?'熔炉 · 全部重铸':'精灵古根 · 洗点道具'}</small><p>${token?'每枚生成一次全重铸候选<br>保留原属性也会消耗印记':'每枚提供10点返还额度<br>在天赋页选择属性后确认使用'}</p><div class="shopGearPrice">${o.price} ◈</div><button data-buy-consumable="${o.offerId}" data-shop-quote="${shop.revision}" ${!o.stock||s.gold<o.price||!canReceiveItem(s,o.consumable,1)?'disabled':''}>${!o.stock?'售罄':!canReceiveItem(s,o.consumable,1)?'道具包已满':'购入1枚'}</button></article>`;}const m=MATERIALS[o.material],key=materialKey(o.material,o.quality??0),max=maxPurchase(o),q=buyQuantities[key]=Math.max(1,Math.min(buyQuantities[key]||1,max||1));return `<article class="commodityCard materialCommodity r${o.quality??0}"><div class="commodityTop">${materialVisual(key)}<div><h3 class="r${o.quality??0}text">${esc(m.name??o.material)}</h3><small>${RARITY[o.quality??0]} · ${esc(m.origin)}</small></div><b>${o.price}◈<small>/ 件</small></b></div><p>${esc(m.description)}</p><div class="stockLine"><span>库存 ${o.stock}</span><span>持有 ${materialCount(s,o.material,o.quality??0)}</span></div><div class="quantityControls"><button data-quantity="${key}" data-delta="-1" ${q<=1?'disabled':''} aria-label="减少${esc(m.name??o.material)}数量">−</button><input id="buyQty${i}" data-buyqty="${key}" type="number" min="1" max="${max||1}" step="1" value="${q}" aria-label="${esc(m.name??o.material)}购买数量" ${!max?'disabled':''}><button data-quantity="${key}" data-delta="1" ${q>=max?'disabled':''} aria-label="增加${esc(m.name??o.material)}数量">＋</button><button data-quantity="${key}" data-max="1" ${!max?'disabled':''}>最多</button></div><button class="primary commodityBuy" data-buy-material="${key}" data-shop-quote="${shop.revision}" ${!max||Date.now()<buyLockUntil?'disabled':''}>${!o.stock?'售罄':!canReceiveMaterial(s,key,1)?'材料包已满':!max?'金币不足':'购买 '+q+' 件 · '+q*o.price+'◈'}</button></article>`}).join('')}</div><div class="merchantRefresh"><span id="merchantTimer">${merchantCountdown(shop)}</span><button data-shop-refresh="1" data-shop-quote="${shop.revision}" ${s.gold<getMerchantRefreshCost(s)||Date.now()<buyLockUntil?'disabled':''}>换一批 · ${getMerchantRefreshCost(s)}◈</button></div><div class="merchantFooter"><p class="subtleText">每30分钟自动换货，离线也计时。手动本周期20、30、40…金币，不推迟自动换货；新货可能重复，不保证特定材料。每批8个货位，材料与非套装装备随机上架；游商不出售套装。材料不限当前副本；装备属性已生成，购买不会重掷。材料包括本地材料与跨族进口货品；进口不代表其他族地图已开放。</p><button data-sellall="1">按部位批量出售</button></div></div></div>`;}
function journalView(){heading('诸境纪事','THE MISSING CARAVAN','<button data-log="1">战斗记录</button>');$('worldStatus').textContent='五族的旧盟约已经崩塌，商队是最后一条补给线。';return `<div class="panelPage"><div class="questCards">${LOCS.map((l,i)=>`<div class="questCard ${s.bossWins[i]?'done':''}">${icon(['sword','forge','shield'][i])}<h3>${l.name}</h3><p>${s.bossWins[i]?'✓ 线索已找到':'击败首领寻找线索'}</p></div>`).join('')}</div>${s.chronicle.map(t=>`<div class="chronicle">${esc(t)}</div>`).join('')}<p class="subtleText">已胜利 ${s.kills} 场 · 纪事为章节事件，非完整政治模拟</p></div>`;}
function codexView(){heading('诸境图鉴','RECORDS OF THE JOURNEY');$('worldStatus').textContent=codexTab==='monsters'?'实际遭遇即记录怪物见闻；点材料查看已开放来源。':'记录曾经真正获得的套装部位与传说；出售或消耗后保留记忆，不提供属性奖励。';return codexTab==='monsters'?renderMonsterCodex(s,{selectedMonster:selectedCodexMonster}):renderCodex(s,{tab:codexTab,selectedSet:selectedCodexSet,selectedLegend:selectedCodexLegend}).replace('</nav>','<button data-codex-tab="monsters">怪物见闻</button></nav>');}
function render(){if(skillTreeMount){skillTreeMount.dispose();skillTreeMount=null;}if(regionMount){regionUi=regionMount.getUI();regionMount.dispose();regionMount=null;}for(const dispose of battleBindings)dispose();battleBindings=[];hud();$('view').innerHTML=(sandboxSession?renderDevelopmentNotice():'')+({world:worldView,region:regionView,battle:battleView,inventory:inventoryView,skills:skillsView,skilltree:skillTreeView,forge:forgeView,loadouts:loadoutsView,merchant:merchantView,journal:journalView,codex:codexView}[view])();if(view==='inventory')portrait($('doll'));if(view==='world')drawWorld($('worldCanvas'),0);if(view==='region'&&race!=='dwarf')drawRegion($('regionCanvas'),race,0);bindRegionView();bindSkillTreeView();bindIntegratedViews();battleHud();if(view==='battle')livePixel.load().then(()=>{if(view==='battle')syncLiveBattle();});}
function refreshEnemyRoster(){const host=$('enemyRosterHost');if(!host)return;const html=renderEnemyRoster(e);if(host.__rosterHtml===html)return;const active=document.activeElement,key=active?.dataset?.enemyTarget?['enemyTarget',active.dataset.enemyTarget]:active?.dataset?.unitDetail?['unitDetail',active.dataset.unitDetail]:null;const restore=key&&host.contains?.(active);host.innerHTML=html;host.__rosterHtml=html;if(restore){const next=Array.from(host.querySelectorAll?.('button')??[]).find(b=>b.dataset[key[0]]===key[1]&&!b.disabled);next?.focus?.();}}
function battleHud(){syncLiveBattle();if(view==='battle'){refreshEnemyRoster();if($('playerShieldHost'))$('playerShieldHost').innerHTML=renderPlayerShieldSummary(e);}if(potionSettingsOpen&&$('modal').open)$('modalBody').innerHTML=renderPotionSettings(s);if(restSeconds())$('activityStatus').textContent='休息 '+restLabel()+(s.restResume&&s.running?' · 随后续战':'');if(!['battle','inventory'].includes(view))return;if($('potionPanelHost'))$('potionPanelHost').innerHTML=potionView();if(view==='battle'&&$('battlePotionHost'))$('battlePotionHost').innerHTML=renderBattlePotionButton(s);if(view!=='battle')return;if(lastBattleSite!==(currentPlannedNode()?.id||s.location)){battleHeading();lastBattleSite=currentPlannedNode()?.id||s.location;}updateRouteControls();$('combatStatuses').innerHTML=e&&!e.done?['hero','enemy'].map(side=>{const rows=combatStatuses(e).filter(x=>x.side===side);return rows.length?`<div class="statusGroup ${side}"><small>${side==='hero'?'布洛克':'敌人'}</small>${rows.map(x=>{const duration=Number.isFinite(x.remainingSeconds)?Math.ceil(x.remainingSeconds)+'秒':x.turns+'回合';return `<span class="statusChip" title="${esc(x.name)} · ${duration}" aria-label="${esc(x.name)}剩余${duration}">${icon(x.key)}<b>${Number.isFinite(x.remainingSeconds)?Math.ceil(x.remainingSeconds)+'s':x.turns}</b></span>`;}).join('')}</div>`:'';}).join(''):'';let st=stats(s),hp=s.heroHp??st.hp;$('heroHp').textContent=Math.ceil(hp)+'/'+st.hp;$('heroHpBar').style.width=Math.min(100,hp/st.hp*100)+'%';$('enemyName').textContent=e?e.name:'未知敌人';$('enemyElements').textContent=e?(e.elementTags||[]).map(k=>ELEMENTS[k]?.name||'').join('·')||'抗性':'元素';$('enemyElements').disabled=!e;$('enemyHp').textContent=e?Math.max(0,Math.ceil(e.hp))+'/'+e.max:'—';$('enemyHpBar').style.width=(e?Math.max(0,e.hp/e.max*100):100)+'%';$('battleState').textContent=restSeconds()?'营地休息 · '+restLabel():s.running?(e?.boss?'首领战 · 回合 '+e.round:(e?.kind==='dungeon'?'普通副本 '+e.dungeonStage+'/3 · 回合 ':'野外挂机 · 回合 ')+(e?.round||0)):'已停止远征';$('stopAfterBtn').textContent=s.stopAfterBattle?'取消结束后停止':'本场结束后停止';$('stopAfterBtn').disabled=!!sandboxSession||!s.running&&(!e||e.done);$('runBtn').textContent=restSeconds()?(s.restResume&&s.running?'取消续战 · ':'休息 ')+restLabel():s.running?'Ⅱ 暂停':currentPlannedNode()?.kind==='boss'?'⚔ 挑战首领':'▶ 开始远征';$('runBtn').disabled=restSeconds()>0&&!(s.restResume&&s.running);if($('campRestBtn'))$('campRestBtn').disabled=restSeconds()>0;const bossNode=plannedNodes().find(n=>n.areaNumber===(currentPlannedNode()?.areaNumber||selectedPlannedArea)&&n.kind==='boss'),cd=Math.max(0,Math.ceil(((bossNode?.readyAt||0)-Date.now())/1000));$('bossBtn').hidden=!bossNode;$('bossBtn').textContent=cd?'首领冷却 '+cd+'s':'挑战首领';$('bossBtn').disabled=!!sandboxSession||!bossNode?.unlocked||!bossNode?.budgetReady||restSeconds()>0||cd>0||!!(e&&!e.done);if(sandboxSession&&e?.done)$('runBtn').disabled=true;}
function resetFight(){e=null;nextAt=0;lastStep=Date.now();render();save();}function start(boss=false){if(sandboxSession)return toast('开发遭遇已独立运行；请使用测试入口或退出测试。');if(boss&&e&&!e.done)return toast('请先结束当前战斗，再挑战首领');if(!canStartEncounter(s)){s.running=false;save();render();return toast(restSeconds()?'营地休息尚未结束：'+restLabel():'战后整备中，请稍候');}const bossNode=plannedNodes().find(n=>n.areaNumber===(currentPlannedNode()?.areaNumber||selectedPlannedArea)&&n.kind==='boss');const tx=persistGameChange(next=>boss?(bossNode&&startInstanceEncounter(next,bossNode.id)):startRoutedEncounter(next));e=s.activeEncounter??null;if(!tx.ok||!tx.value){render();return toast('地点未就绪、尚在冷却，或需要重新选择区域');}if(!e)return;s.running=true;lastStep=Date.now();logs.unshift((boss?'首领现身：':'遭遇 ')+e.name);hud();battleHud();save();}
function clearBatchSale(){batchSaleActive=false;batchSaleQuote=null;batchSaleQualities=[];batchSaleError='';batchSalePage=0;}
function renderBatchSalePreview(){if(batchSaleActive)modal(renderBatchSale(s,{slot:batchSaleSlot,qualities:batchSaleQualities,quote:batchSaleQuote,error:batchSaleError,page:batchSalePage}));}
function refreshBatchSalePreview(){batchSalePage=0;batchSaleQuote=quoteBatchSale(s,batchSaleSlot,batchSaleQualities);batchSaleError='';renderBatchSalePreview();}
function openBatchSale(){bagTab='equipment';if(view!=='inventory')go('inventory');batchSaleSlot=bagSlot;batchSaleQualities=[];batchSaleActive=true;refreshBatchSalePreview();}
